// Card image URLs by card key. The WebP files are generated by
// `npm run build:card-images` (see CREDITS.md for sources). Vite emits them as hashed
// assets, and the service worker precaches them so every card works offline.

export const CARD_IMAGE_SIZES = ['thumb', 'full'] as const;
export type CardImageSize = (typeof CARD_IMAGE_SIZES)[number];

const urls = import.meta.glob<string>('./cards/*/*.webp', {
  eager: true,
  query: '?no-inline',
  import: 'default',
});

/** URL of a card's image: `thumb` (~160 px wide) for grids and pickers, `full` (~600 px). */
export function cardImageUrl(key: string, size: CardImageSize): string {
  const url = urls[`./cards/${size}/${key}.webp`];
  if (url === undefined) throw new Error(`No ${size} image for card ${key}`);
  return url;
}
